#!/bin/sh
# Generated by `rpg install-hooks`. Do not edit: re-running the installer overwrites it.
# Reports commits/pushes to rpg, then hands over to the hook git would otherwise have run.
# It must never fail or slow down a git operation on its own.
RPG_BIN=__RPG_BIN__
HOOK=__HOOK__
PREV=__PREV__
# The RPG_HOME in effect at install time ("" = default dirs). Passed as `--home`, so events go
# to the home these shims belong to, whatever RPG_HOME the committing shell has.
RPG_HOME_DIR=__HOME__

# 0. Locate this repo's git dirs using shell builtins only (no extra processes): git runs hooks
#    from the work-tree root, or from $GIT_DIR in a bare repo. `gitdir` is per-worktree
#    (rebase state lives there); `common` holds the shared hooks/ dir.
gitdir=${GIT_DIR:-}
if [ -z "$gitdir" ]; then
  if [ -d .git ]; then
    gitdir=.git
  elif [ -f .git ]; then
    read -r line < .git
    gitdir=${line#gitdir: }
  else
    gitdir=$(git rev-parse --git-dir 2>/dev/null </dev/null)
  fi
fi
common=${GIT_COMMON_DIR:-}
if [ -z "$common" ] && [ -n "$gitdir" ]; then
  if [ -f "$gitdir/commondir" ]; then
    read -r c < "$gitdir/commondir"
    case "$c" in
      /* | [A-Za-z]:*) common=$c ;;
      *) common="$gitdir/$c" ;;
    esac
  else
    common=$gitdir
  fi
fi

# 1. Tell rpg, in the background, detached from git's stdin/stdout/stderr.
if [ -f "$RPG_BIN" ]; then
  case "$HOOK" in
    post-commit)
      # Commits replayed by a rebase are not new work.
      if [ ! -d "$gitdir/rebase-merge" ] && [ ! -d "$gitdir/rebase-apply" ]; then
        top=$(git rev-parse --show-toplevel 2>/dev/null </dev/null)
        head=$(git rev-parse HEAD 2>/dev/null </dev/null)
        if [ -n "$top" ] && [ -n "$head" ]; then
          "$RPG_BIN" emit commit --repo "$top" --hash "$head" ${RPG_HOME_DIR:+--home "$RPG_HOME_DIR"} </dev/null >/dev/null 2>&1 &
          # This commit may conclude a conflicted merge (marker from prepare-commit-msg below).
          # Rename it so the next commit can't see it; rpg checks it against HEAD^2 and deletes it.
          if [ -f "$gitdir/rpg-conflict" ] && mv -f "$gitdir/rpg-conflict" "$gitdir/rpg-conflict-$head" 2>/dev/null; then
            "$RPG_BIN" emit merge-conflict --repo "$top" --hash "$head" --marker "$gitdir/rpg-conflict-$head" ${RPG_HOME_DIR:+--home "$RPG_HOME_DIR"} </dev/null >/dev/null 2>&1 &
          fi
        fi
      fi
      ;;
    prepare-commit-msg)
      # A commit concluding a merge that stopped on conflicts: git listed the conflicted paths in
      # MERGE_MSG under "# Conflicts:". MERGE_HEAD and MERGE_MSG are gone by post-commit, so note
      # the merge and its paths in a marker. Builtins only: no extra processes on any commit.
      if [ -f "$gitdir/MERGE_HEAD" ] && [ -f "$gitdir/MERGE_MSG" ] && [ ! -d "$gitdir/rebase-merge" ] && [ ! -d "$gitdir/rebase-apply" ]; then
        read -r mh < "$gitdir/MERGE_HEAD"
        files=
        sect=
        while IFS= read -r l || [ -n "$l" ]; do
          case "$l" in
            ?" Conflicts:") sect=1 ;;
            ?"	"*) [ -n "$sect" ] && files="$files${l#??}
" ;;
            *) sect= ;;
          esac
        done < "$gitdir/MERGE_MSG"
        if [ -n "$mh" ] && [ -n "$files" ]; then
          printf '%s
%s' "$mh" "$files" > "$gitdir/rpg-conflict" 2>/dev/null
        fi
      fi
      ;;
    pre-push)
      top=$(git rev-parse --show-toplevel 2>/dev/null </dev/null)
      if [ -n "$top" ]; then
        "$RPG_BIN" emit push --repo "$top" --remote "$1" ${RPG_HOME_DIR:+--home "$RPG_HOME_DIR"} </dev/null >/dev/null 2>&1 &
      fi
      ;;
  esac
fi

# 2. Chain to the hook that would have run without us. exec keeps stdin, args and exit code.
if [ -n "$PREV" ]; then
  next="$PREV/$HOOK"
elif [ -n "$common" ]; then
  next="$common/hooks/$HOOK"
else
  exit 0
fi
if [ -f "$next" ] && [ -x "$next" ]; then
  exec "$next" "$@"
fi

# 3. No hook to chain to. push-to-checkout is special: its mere existence makes git skip the
#    built-in receive.denyCurrentBranch=updateInstead logic, so reproduce that logic here.
if [ "$HOOK" = push-to-checkout ]; then
  git update-index -q --ignore-submodules --refresh || { echo "Up-to-date check failed" >&2; exit 1; }
  git diff-files --quiet --ignore-submodules -- || { echo "Working directory has unstaged changes" >&2; exit 1; }
  if git rev-parse -q --verify HEAD >/dev/null 2>&1; then
    base=HEAD
  else
    base=$(git hash-object -t tree /dev/null)
  fi
  git diff-index --quiet --cached --ignore-submodules "$base" -- || { echo "Working directory has staged changes" >&2; exit 1; }
  exec git read-tree -u -m "$1"
fi
exit 0
